ALTER TABLE public.products ADD COLUMN price_unit text NOT NULL DEFAULT 'piece' CHECK(price_unit IN ('piece','pack')), ADD COLUMN pack_size integer NOT NULL DEFAULT 1 CHECK(pack_size BETWEEN 1 AND 100000), ADD COLUMN composition text NOT NULL DEFAULT '' CHECK(length(composition)<=2000), ADD COLUMN non_plastic boolean NOT NULL DEFAULT false, ADD COLUMN volume_discounts jsonb NOT NULL DEFAULT '[]';
ALTER TABLE public.orders ADD COLUMN delivery jsonb NOT NULL DEFAULT '{}', ADD COLUMN request_key uuid, ADD COLUMN is_demo boolean NOT NULL DEFAULT false;
CREATE UNIQUE INDEX order_request_supplier ON public.orders(buyer_id,request_key,supplier_id);
ALTER TABLE public.order_items ADD COLUMN name_en text NOT NULL DEFAULT '', ADD COLUMN name_ar text NOT NULL DEFAULT '', ADD COLUMN price_unit text NOT NULL DEFAULT 'piece', ADD COLUMN pack_size integer NOT NULL DEFAULT 1;
CREATE TABLE public.product_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, storage_path text NOT NULL CHECK(length(storage_path)<=1000), file_name text NOT NULL CHECK(length(file_name)<=255));
GRANT SELECT ON public.product_documents TO anon; GRANT SELECT,INSERT,DELETE ON public.product_documents TO authenticated; GRANT ALL ON public.product_documents TO service_role;
ALTER TABLE public.product_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY product_document_read ON public.product_documents FOR SELECT USING(public.public_product(product_id) OR EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND public.owns_supplier(p.supplier_id)) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY product_document_write ON public.product_documents FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND public.owns_supplier(p.supplier_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND public.owns_supplier(p.supplier_id)) AND split_part(storage_path,'/',1)=auth.uid()::text);
CREATE OR REPLACE FUNCTION public.public_product(pid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.products p JOIN public.supplier_profiles s ON s.id=p.supplier_id WHERE p.id=pid AND p.status='published' AND p.non_plastic AND p.material IN ('bagasse','kraft','wood','cardboard','cotton','beeswax') AND s.verification_status='approved' AND NOT p.is_demo AND NOT s.is_demo) $$;
CREATE FUNCTION public.validate_product_marketplace() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE tier jsonb; previous_qty integer:=0; previous_price numeric; BEGIN
IF auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'admin') AND NOT EXISTS(SELECT 1 FROM public.supplier_profiles WHERE id=NEW.supplier_id AND user_id=auth.uid() AND verification_status='approved') THEN RAISE EXCEPTION 'Supplier approval required'; END IF;
IF jsonb_typeof(NEW.volume_discounts)<>'array' OR jsonb_array_length(NEW.volume_discounts)>10 THEN RAISE EXCEPTION 'Invalid discounts'; END IF; previous_price:=NEW.price;
FOR tier IN SELECT value FROM jsonb_array_elements(NEW.volume_discounts) LOOP IF (tier->>'min_quantity')::numeric <> trunc((tier->>'min_quantity')::numeric) OR (tier->>'min_quantity')::integer<=previous_qty OR (tier->>'min_quantity')::integer<NEW.moq OR (tier->>'unit_price')::numeric<=0 OR (tier->>'unit_price')::numeric>=previous_price OR tier->>'min_quantity' IS NULL OR tier->>'unit_price' IS NULL THEN RAISE EXCEPTION 'Invalid discount tier'; END IF; previous_qty:=(tier->>'min_quantity')::integer; previous_price:=(tier->>'unit_price')::numeric; END LOOP;
IF NEW.status='published' AND (NOT NEW.non_plastic OR NEW.material NOT IN ('bagasse','kraft','wood','cardboard','cotton','beeswax') OR length(trim(NEW.composition))=0 OR NOT EXISTS(SELECT 1 FROM public.supplier_profiles WHERE id=NEW.supplier_id AND verification_status='approved')) THEN RAISE EXCEPTION 'Only eligible non-plastic packaging may be published'; END IF;
IF TG_OP='UPDATE' AND auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'admin') AND OLD.status='published' AND (NEW.composition,NEW.non_plastic,NEW.category_slug) IS DISTINCT FROM (OLD.composition,OLD.non_plastic,OLD.category_slug) THEN NEW.status:='pending'; END IF; RETURN NEW; END $$;
CREATE TRIGGER marketplace_product_validation BEFORE INSERT OR UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.validate_product_marketplace();
CREATE OR REPLACE FUNCTION public.validate_cart_quantity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p public.products; BEGIN SELECT * INTO p FROM public.products WHERE id=NEW.product_id; IF p.id IS NULL OR NEW.quantity<p.moq OR NEW.quantity>p.stock OR NEW.quantity>1000000 THEN RAISE EXCEPTION 'Invalid quantity or insufficient stock'; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.market_unit_price(base numeric, tiers jsonb, qty integer) RETURNS numeric LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT round(COALESCE((SELECT (value->>'unit_price')::numeric FROM jsonb_array_elements(tiers) WHERE (value->>'min_quantity')::integer<=qty ORDER BY (value->>'min_quantity')::integer DESC LIMIT 1),base),2) $$;
CREATE FUNCTION public.request_cart_order(request_id uuid, address jsonb) RETURNS SETOF uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); line record; oid uuid; sid uuid; BEGIN
IF uid IS NULL OR NOT public.has_role(uid,'buyer') THEN RAISE EXCEPTION 'Buyer access required'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,0));
IF EXISTS(SELECT 1 FROM public.orders WHERE buyer_id=uid AND request_key=request_id) THEN RETURN QUERY SELECT id FROM public.orders WHERE buyer_id=uid AND request_key=request_id; RETURN; END IF;
IF address IS NULL OR jsonb_typeof(address)<>'object' OR length(trim(COALESCE(address->>'name','')))<1 OR length(address->>'name')>100 OR length(COALESCE(address->>'phone','')) NOT BETWEEN 5 AND 30 OR length(trim(COALESCE(address->>'city','')))<1 OR length(address->>'city')>100 OR length(trim(COALESCE(address->>'address','')))<5 OR length(address->>'address')>500 OR length(COALESCE(address->>'notes',''))>1000 THEN RAISE EXCEPTION 'Invalid delivery information'; END IF;
PERFORM 1 FROM public.shopping_carts WHERE user_id=uid FOR UPDATE;
PERFORM 1 FROM public.cart_items ci JOIN public.shopping_carts c ON c.id=ci.cart_id WHERE c.user_id=uid FOR UPDATE OF ci;
IF NOT EXISTS(SELECT 1 FROM public.cart_items ci JOIN public.shopping_carts c ON c.id=ci.cart_id WHERE c.user_id=uid) THEN RAISE EXCEPTION 'Cart is empty'; END IF;
FOR line IN SELECT p.*,ci.quantity FROM public.cart_items ci JOIN public.shopping_carts c ON c.id=ci.cart_id JOIN public.products p ON p.id=ci.product_id WHERE c.user_id=uid ORDER BY p.id FOR UPDATE OF p LOOP
IF NOT public.public_product(line.id) OR line.quantity<line.moq OR line.quantity>line.stock OR line.quantity>1000000 THEN RAISE EXCEPTION 'Product unavailable or invalid quantity'; END IF;
SELECT id INTO oid FROM public.orders WHERE buyer_id=uid AND request_key=request_id AND supplier_id=line.supplier_id;
IF oid IS NULL THEN INSERT INTO public.orders(buyer_id,supplier_id,status,total,delivery,request_key) VALUES(uid,line.supplier_id,'pending',0,address,request_id) RETURNING id INTO oid; END IF;
INSERT INTO public.order_items(order_id,product_id,quantity,unit_price,name_en,name_ar,price_unit,pack_size) VALUES(oid,line.id,line.quantity,public.market_unit_price(line.price,line.volume_discounts,line.quantity),line.name_en,line.name_ar,line.price_unit,line.pack_size);
UPDATE public.products SET stock=stock-line.quantity WHERE id=line.id;
END LOOP;
UPDATE public.orders o SET total=(SELECT sum(quantity*unit_price) FROM public.order_items WHERE order_id=o.id) WHERE buyer_id=uid AND request_key=request_id;
DELETE FROM public.cart_items WHERE cart_id IN(SELECT id FROM public.shopping_carts WHERE user_id=uid);
RETURN QUERY SELECT id FROM public.orders WHERE buyer_id=uid AND request_key=request_id; END $$;
REVOKE ALL ON FUNCTION public.request_cart_order(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.request_cart_order(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.change_order_status(order_id uuid, next_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; line record; uid uuid:=auth.uid(); allowed boolean:=false; BEGIN
SELECT * INTO o FROM public.orders WHERE id=order_id FOR UPDATE;
IF uid IS NULL OR o.id IS NULL THEN RAISE EXCEPTION 'Order not found'; END IF;
IF o.buyer_id=uid AND next_status='cancelled' AND o.status IN ('pending','accepted') THEN allowed:=true; END IF;
IF public.owns_supplier(o.supplier_id) THEN allowed:=allowed OR (o.status='pending' AND next_status IN ('accepted','rejected')) OR (o.status='accepted' AND next_status IN ('processing','cancelled')) OR (o.status='processing' AND next_status='shipped') OR (o.status='shipped' AND next_status='delivered'); END IF;
IF NOT allowed THEN RAISE EXCEPTION 'Invalid status transition or access denied'; END IF;
IF next_status IN ('rejected','cancelled') THEN FOR line IN SELECT * FROM public.order_items WHERE order_items.order_id=o.id ORDER BY product_id LOOP UPDATE public.products SET stock=stock+line.quantity WHERE id=line.product_id; END LOOP; END IF;
UPDATE public.orders SET status=next_status WHERE id=o.id; END $$;
REVOKE ALL ON FUNCTION public.change_order_status(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.change_order_status(uuid,text) TO authenticated;
CREATE POLICY media_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='product-media' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.products p WHERE p.id::text=(storage.foldername(name))[2] AND public.owns_supplier(p.supplier_id)));
CREATE POLICY media_read ON storage.objects FOR SELECT USING(bucket_id='product-media' AND EXISTS(SELECT 1 FROM public.products p WHERE p.id::text=(storage.foldername(name))[2] AND (public.public_product(p.id) OR public.owns_supplier(p.supplier_id) OR public.has_role(auth.uid(),'admin'))));
CREATE POLICY media_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='product-media' AND (storage.foldername(name))[1]=auth.uid()::text);